// The permission⇄tool matrix (issue #30 AC4/AC4d): ONE declarative table
// answering "which chrome permission backs which agent tool, at which tier"
// plus a bidirectional checker that keeps the manifest, this table and the
// tool registry in lockstep. Every other surface derives its permission
// facts from `manifestEntries()` — a permission that drifts from the table
// surfaces as a MatrixViolation instead of a silent gap. The three tiers
// mirror the v2.1 inventory: registered-and-exposed (core), implemented but
// Settings-gated (secondTier), and deliberately absent everywhere
// (excluded — the row documents why, so absence is auditable, not
// accidental). Pure Dart: compiles into the MV3 service worker, so no
// dart:io and no js_interop.
library;

/// How a tool (or permission) sits in the v2.1 inventory.
enum MatrixTier {
  /// Registered and exposed to the agent; an unpacked manifest must carry
  /// the permission.
  core,

  /// Implemented but not registered by default — a Settings gate turns it
  /// on; its permission may ride `optional_permissions`.
  secondTier,

  /// Deliberately absent from manifest AND registry; the table row's
  /// rationale documents why so the absence is auditable.
  excluded,
}

/// One row of the declarative permission⇄tool table.
final class ToolManifestEntry {
  /// Tool name as the registry keys it (equals the chrome namespace for
  /// single-namespace tools).
  final String tool;

  /// chrome manifest permission names backing the tool (empty when the
  /// namespace needs no permission, e.g. `runtime`).
  final Set<String> permissions;

  /// Which inventory tier the tool belongs to.
  final MatrixTier tier;

  /// chrome.* namespace backing the tool when it differs from [tool]
  /// (composite tools); null means [tool] names the namespace itself.
  final String? apiGroup;

  /// True only for rows impossible by construction — chrome exposes no API
  /// at all — recorded so no tool may ever probe for one.
  final bool impossible;

  /// Why an [MatrixTier.excluded] row stays out; null for other tiers.
  final String? rationale;

  const ToolManifestEntry({
    required this.tool,
    required this.permissions,
    required this.tier,
    this.apiGroup,
    this.impossible = false,
    this.rationale,
  });
}

/// The full v2.1 inventory, one row per tool. This list is the single
/// source of truth: `checkMatrix` classifies every permission and tool name
/// against it, and the registry⇄table test pins the live registry to it.
const List<ToolManifestEntry> _table = [
  // --- core: registered and driven by the agent ---
  ToolManifestEntry(tool: 'tabs', permissions: {'tabs'}, tier: MatrixTier.core),
  ToolManifestEntry(
    tool: 'windows',
    permissions: {'windows'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'tabGroups',
    permissions: {'tabGroups'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'sessions',
    permissions: {'sessions'},
    tier: MatrixTier.core,
  ),
  // Reading/download surfaces the v2.1 registry drives (browser_api_tools:
  // history_search, bookmarks_*, downloads_*, cookies_*, nav_wait) and the
  // ChromeApi facade covers — same core tier, same manifest requirement.
  ToolManifestEntry(
    tool: 'history',
    permissions: {'history'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'bookmarks',
    permissions: {'bookmarks'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'downloads',
    permissions: {'downloads'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'cookies',
    permissions: {'cookies'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'webNavigation',
    permissions: {'webNavigation'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'scripting',
    permissions: {'scripting'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'debugger',
    permissions: {'debugger'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'storage',
    permissions: {'storage'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    // Whole-tree session fs snapshots (faFs) outgrow the default 10 MB
    // chrome.storage.local quota; unlimitedStorage lifts it.
    tool: 'unlimitedStorage',
    permissions: {'unlimitedStorage'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'sidePanel',
    permissions: {'sidePanel'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'action',
    permissions: {'action'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'alarms',
    permissions: {'alarms'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'offscreen',
    permissions: {'offscreen'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'notifications',
    permissions: {'notifications'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'power',
    permissions: {'power'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(tool: 'idle', permissions: {'idle'}, tier: MatrixTier.core),
  ToolManifestEntry(
    tool: 'commands',
    permissions: {'commands'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'contextMenus',
    permissions: {'contextMenus'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'omnibox',
    permissions: {'omnibox'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'identity',
    permissions: {'identity'},
    tier: MatrixTier.core,
  ),
  // chrome.runtime needs no manifest permission.
  ToolManifestEntry(tool: 'runtime', permissions: {}, tier: MatrixTier.core),
  ToolManifestEntry(
    tool: 'system.cpu',
    permissions: {'system.cpu'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'system.memory',
    permissions: {'system.memory'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'system.storage',
    permissions: {'system.storage'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'system.display',
    permissions: {'system.display'},
    tier: MatrixTier.core,
  ),

  // --- second tier: registered-but-hidden behind a Settings gate ---
  ToolManifestEntry(
    tool: 'topSites',
    permissions: {'topSites'},
    tier: MatrixTier.secondTier,
  ),
  ToolManifestEntry(
    tool: 'pageCapture',
    permissions: {'pageCapture'},
    tier: MatrixTier.secondTier,
  ),
  ToolManifestEntry(
    tool: 'desktopCapture',
    permissions: {'desktopCapture'},
    tier: MatrixTier.secondTier,
  ),
  ToolManifestEntry(
    tool: 'userScripts',
    permissions: {'userScripts'},
    tier: MatrixTier.secondTier,
  ),

  // --- bridge-only core (issue #137): permissions the generic chrome.*
  // bridge surfaces with no curated tool. Declared in permissions (the
  // catalog must be truthful), callable through browser_api; risk rides
  // bridgeRiskTier (bridge_tools.dart), the hard deny list still applies. ---
  ToolManifestEntry(
    tool: 'search',
    permissions: {'search'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'readingList',
    permissions: {'readingList'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'tabCapture',
    permissions: {'tabCapture'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'browsingData',
    permissions: {'browsingData'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'tts',
    permissions: {'tts'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'declarativeNetRequest',
    permissions: {'declarativeNetRequest'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'privacy',
    permissions: {'privacy'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'proxy',
    permissions: {'proxy'},
    tier: MatrixTier.core,
  ),
  // Declared for catalog truthfulness; the bridge DENIES chrome.management
  // calls in every mode (self-preservation — see bridgeDeniedNamespaces).
  ToolManifestEntry(
    tool: 'management',
    permissions: {'management'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'clipboard',
    permissions: {'clipboardRead', 'clipboardWrite'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'contentSettings',
    permissions: {'contentSettings'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'fontSettings',
    permissions: {'fontSettings'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'nativeMessaging',
    permissions: {'nativeMessaging'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'webRequest',
    permissions: {'webRequest'},
    tier: MatrixTier.core,
  ),
  // The bridge itself: one row claiming everything only it exposes, so
  // each bridge-only permission above is accounted for at the tool layer.
  ToolManifestEntry(
    tool: 'browser_api',
    permissions: {
      'search',
      'readingList',
      'tabCapture',
      'browsingData',
      'tts',
      'declarativeNetRequest',
      'privacy',
      'proxy',
      'management',
      'clipboardRead',
      'clipboardWrite',
      'contentSettings',
      'fontSettings',
      'nativeMessaging',
      'webRequest',
    },
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'browser_api_catalog',
    permissions: {},
    tier: MatrixTier.core,
  ),

  // --- excluded: absent from manifest and registry, on the record ---
  // (issue #137 moved browsingData/tts/declarativeNetRequest/privacy/
  // proxy/management to core — declared + bridge-gated instead of absent.)
  ToolManifestEntry(
    tool: 'gcm',
    permissions: {'gcm'},
    tier: MatrixTier.excluded,
    rationale: 'push-messaging transport, not an agent surface',
  ),
