    );
  }

  /// Installs `window.__fahQjsRun(code)`, a stdout-capturing QuickJS runner
  /// that reuses one engine instance.
  static const _qjsRunnerSource = r'''
window.__fahQjsRun = function(code) {
  if (!window.__fahQjsPromise) {
