  // ChromeApi facade covers — same core tier, same manifest requirement.
  ToolManifestEntry(
    tool: 'history',
    permissions: {'history'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'bookmarks',
    permissions: {'bookmarks'},
    tier: MatrixTier.core,
