  ToolManifestEntry(tool: 'tabs', permissions: {'tabs'}, tier: MatrixTier.core),
  ToolManifestEntry(
    tool: 'windows',
    permissions: {'windows'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'tabGroups',
    permissions: {'tabGroups'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'sessions',
    permissions: {'sessions'},
    tier: MatrixTier.core,
  ),
