    tool: 'history',
    permissions: {'history'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'bookmarks',
    permissions: {'bookmarks'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'downloads',
    permissions: {'downloads'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
