  ToolManifestEntry(
    tool: 'history',
    permissions: {'history'},
    tier: MatrixTier.core,
  ),
  ToolManifestEntry(
    tool: 'bookmarks',
    permissions: {'bookmarks'},
    tier: MatrixTier.core,
