/// gh-1630 (CWS Blue Argon — MV3 remotely hosted code): the URL must not
/// EXIST in the extension package, even for never-executed paths, so the
/// selection is a compile-time constant keyed on the `FA_HOST` dart-define
/// the packaging build already sets (`--dart-define=FA_HOST=extension`,
/// scripts/build_browser_ext.sh). dart2js const-folds
/// `String.fromEnvironment` and dead-code-eliminates the untaken branch —
/// verified empirically on the CI toolchain: with `-DFA_HOST=extension`
/// no CDN constant survives into the compiled bundle (and the plain web
/// build keeps none of the vendor paths). The packaging guard
/// (scripts/check_cws_compliance.py + ext_package_guard.py) re-checks the
/// REAL built artifact on every packaging build, so a toolchain change
/// that broke the elimination fails the build, not the store review.
///
/// - **Extension build** (`kFaExtBuild`): everything resolves into the
///   package-local vendor dir (`browser_ext/vendor/interpreters/`,
///   checksum-pinned by `browser_ext/vendor.lock.json` +
///   `scripts/fetch_vendor_assets.sh`). The panel app is staged at
///   `panel/app/` with `--base-href=/panel/app/`, so `../../vendor/…`
///   resolves to the extension root's vendor dir — every path stays
///   inside the package (no `chrome.runtime.getURL` needed; nothing is
///   remotely hosted).
/// - **Plain web/office builds**: the public CDN constants the app has
///   always used (fa.dev and the Office taskpane are not CWS-audited and
///   their CSP explicitly allowlists the CDN) — behavior unchanged
///   (gh-1630 I4).
///
/// Pure Dart (no dart:html) so the selection is unit-testable on the VM.
library;

/// Whether this bundle was compiled for the browser extension package.
const bool kFaExtBuild =
    const String.fromEnvironment('FA_HOST') == 'extension';

/// Asset locations for one engine set.
class InterpreterAssets {
  /// `<script>` URL of quickjs-emscripten's self-contained bundle.
  final String quickJsScript;

  /// `<script>` URL of pyodide's classic bootstrap script.
  final String pyodideScript;

  /// `indexURL` passed to `loadPyodide` — the dir holding
  /// pyodide.asm.wasm / python_stdlib.zip / pyodide-lock.json. Explicit in
  /// BOTH builds so the vendored copy cannot fall back to a CDN default.
  final String pyodideIndex;

  /// `<script>` URL of sql.js's loader.
  final String sqlJsScript;

  /// Base dir `locateFile` resolves sql-wasm.wasm against.
  final String sqlJsDist;

  const InterpreterAssets({
    required this.quickJsScript,
    required this.pyodideScript,
    required this.pyodideIndex,
    required this.sqlJsScript,
    required this.sqlJsDist,
  });
}

/// The CDN locations — plain web/office builds (I4).
