{"newText":"/// Browser-hosted Python (pyodide) and JavaScript (quickjs-emscripten)
/// interpreters for the web sandbox.
///
/// Both engines load on first use and cache on `window`. Asset locations
/// are selected per build by `web_interpreters_urls.dart`: the plain web
/// app loads them from the public CDN; the extension package build
/// (`FA_HOST=extension`) resolves them into the checksum-pinned
/// `browser_ext/vendor/interpreters/` dir — the extension must not carry
/// (or fetch) remote code (gh-1630 I1). quickjs-emscripten is the same
/// QuickJS engine that runs as WASM on iOS/Android; pyodide is CPython
/// compiled to WebAssembly for the browser.
class WebInterpreters {
  static InterpreterAssets get _assets => interpreterAssets();","oldText":"/// Browser-hosted Python (pyodide) and JavaScript (quickjs-emscripten)
/// interpreters for the web sandbox.
///
/// Both engines are loaded from public CDNs on first use and cached on
/// `window`; nothing is bundled into the app. quickjs-emscripten is the same
/// QuickJS engine that runs as WASM on iOS/Android; pyodide is CPython
/// compiled to WebAssembly for the browser.
class WebInterpreters {
  static const _quickJsCdn =
      'https://cdn.jsdelivr.net/npm/quickjs-emscripten@0.31.0/dist/index.global.js';
  static const _pyodideCdn =
      'https://cdn.jsdelivr.net/pyodide/v0.26.4/full/pyodide.js';
  static const _sqlJsCdn =
      'https://cdn.jsdelivr.net/npm/sql.js@1.14.1/dist/sql-wasm.js';
  static const _sqlJsDistBase =
      'https://cdn.jsdelivr.net/npm/sql.js@1.14.1/dist/';","path":"flutter_app/lib/sandbox/web_interpreters_web.dart"}

{"newText":"  static Future<void> _ensureQuickJs() {
