    py.setStderr({ batched: function(s) { err.push(s); } });
    var error = null;
    try {
      py.runPython(code);
    } catch (e) {
      error = String((e && e.message) || e);
    }
    return JSON.stringify({ stdout: out.join('\n'), stderr: err.join('\n'), error: error });
  });
