        return JSON.stringify({ stdout: out.join('\n'), stderr: err.join('\n'), error: String((e && e.message) || e) });
      });
    }, function(e) {
      return JSON.stringify({ stdout: '', stderr: '', error: 'failed to load micropip: ' + String((e && e.message) || e) });
    });
  });

